//
// build.rs — compiles the Briev machinery (bridge/counsel.bv) to a native
// static library and links it into this crate. The autogenerated bindings
// (src/bindings.rs) were produced by `brievc bindings bridge/counsel.bv rust`
// and are checked in; regenerate + commit them when exports change.
//
// The `BRIEVC` env var selects the compiler binary (default "brievc" on PATH).
// This mirrors the proven rust-host GLUE pattern (Path A: LLVM LTO / C ABI).

use std::env;
use std::path::PathBuf;
use std::process::Command;

fn main() {
    // Resolve the Briev compiler from BRIEVC, else PATH.
    let brievc = env::var("BRIEVC").unwrap_or_else(|_| "brievc".to_string());

    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let bridge = manifest.join("bridge/counsel.bv");
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    let lib_out = out.join("briev");

    // Run `brievc build bridge/counsel.bv --library --out $OUT_DIR/briev`.
    let build = Command::new(&brievc)
        .arg("build")
        .arg(&bridge)
        .arg("--library")
        .arg("--out")
        .arg(&lib_out)
        .output()
        .expect("failed to spawn brievc build --library");
    assert!(
        build.status.success(),
        "brievc build --library failed\n{}",
        String::from_utf8_lossy(&build.stderr)
    );

    // Link the produced static library; rebuild when the machinery changes.
    println!("cargo:rustc-link-search=native={}", lib_out.display());
    println!("cargo:rustc-link-lib=counsel");
    println!("cargo:rerun-if-changed={}", bridge.display());
}
